SourceCode.Declaration:
/// <summary>
/// Extends <c>McpBusinessSkillFromResourceProvider</c> to register all built-in Docentric Invoice Delivery Agent skill resources.
/// This ensures related skills are automatically synced via <c>McpBusinessSkillSyncSetupAsync</c> on every deploy.
/// </summary>
/// <remarks>
/// This provider extension class and skills in resource files are needed only if McpBusinessSkillMetadataProviderFlight flight is not enabled 
/// and skills from skills AOT objects are not loaded.
/// </remarks>
[ExtensionOf(classStr(McpBusinessSkillFromResourceProvider))]
internal final class McpBusinessSkillFromResourceProvider_DIDA_Extension
{
}

Method.Source:
    /// <summary>
    /// Appends the invoice delivery investigation skill resource to the list of skills to be published.
    /// </summary>
    /// <returns>The updated <c>List</c> of resource names.</returns>
    public List skillResourceNames()
    {
        List names = next skillResourceNames();

        names.addEnd(resourceStr(DocInvoiceEmailInvestigationSkill));

        return names;
    }
